CARDIO.register({"item":"p204","meta":{"num":"p204","label":"204","spe":"pneumo","short":"Toux chez l'adulte","title":"Toux chez l'adulte","section":"P","chapter":8,"pages":"113-122","sdd":[]},"objectives":[{"id":"p204-obj-01","rank":"A","rubric":"Contenu multimédia","title":"Exemples caractéristiques de radiographie thoracique","desc":""},{"id":"p204-obj-02","rank":"A","rubric":"Définition","title":"Définition de la toux aigüe et chronique chez l'adulte","desc":""},{"id":"p204-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Toux aigüe de l'adulte : principales hypothèses diagnostiques","desc":""},{"id":"p204-obj-04","rank":"A","rubric":"Diagnostic positif","title":"Toux chronique de l'adulte : principales hypothèses diagnostiques","desc":""},{"id":"p204-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Connaître la sémiologie d'une toux et les signes associés à la toux","desc":""},{"id":"p204-obj-06","rank":"B","rubric":"Éléments physiopathologiques","title":"Mécanisme du réflexe de toux","desc":""},{"id":"p204-obj-07","rank":"B","rubric":"Examens complémentaires","title":"Connaître l'indication des examens d'imagerie devant une toux de l'adulte","desc":""},{"id":"p204-obj-08","rank":"A","rubric":"Identifier une urgence","title":"Rechercher les signes de gravité devant une toux aigüe ou chronique","desc":""},{"id":"p204-obj-09","rank":"A","rubric":"Prise en charge","title":"Traitement symptomatique de la toux","desc":""},{"id":"p204-obj-10","rank":"B","rubric":"Prise en charge","title":"Éléments de prise en charge étiologique","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p204-qroc-001","type":"QROC","rank":"A","objective":"p204-obj-02","tags":["définition"],"difficulty":1,"question":"Quelle durée maximale d'évolution, en semaines, définit une toux aiguë de l'adulte ?","answer":"3 semaines","accept":["3 semaines","3","trois semaines","moins de 3 semaines"],"keywords":["3"],"explanation":"Toux aiguë = durée inférieure à 3 semaines ; toux chronique = durée supérieure à 8 semaines ; entre les deux, la toux est subaiguë. La toux aiguë accompagne le plus souvent une infection respiratoire haute virale et s'améliore spontanément en 3 semaines.","src":"p. 114-115"},{"id":"p204-qroc-002","type":"QROC","rank":"A","objective":"p204-obj-02","tags":["définition"],"difficulty":1,"question":"Au-delà de combien de semaines d'évolution une toux est-elle dite chronique ?","answer":"8 semaines","accept":["8 semaines","8","huit semaines","plus de 8 semaines"],"keywords":["8"],"explanation":"Toux chronique = durée supérieure à 8 semaines. Elle ne s'améliore pas spontanément et nécessite une prise en charge spécifique : les durées définies servent à séparer ces deux entités.","src":"p. 114-115"},{"id":"p204-qroc-003","type":"QROC","rank":"A","objective":"p204-obj-02","tags":["définition"],"difficulty":2,"question":"Comment qualifie-t-on une toux qui évolue depuis 5 semaines ?","answer":"Toux subaiguë","accept":["subaiguë","toux subaiguë","subaiguë (entre 3 et 8 semaines)"],"keywords":["subaigu"],"explanation":"La toux subaiguë dure plus de 3 semaines et moins de 8 semaines.","src":"p. 115"},{"id":"p204-qroc-004","type":"QROC","rank":"A","objective":"p204-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quelle est la cause de très loin la plus fréquente d'une toux aiguë isolée chez l'adulte ?","answer":"Une infection respiratoire haute d'origine virale","accept":["infection respiratoire haute","infections respiratoires hautes","rhinopharyngite aiguë","rhinopharyngite","infection virale des voies respiratoires hautes"],"keywords":["haute"],"explanation":"Isolée, la toux aiguë est très majoritairement secondaire à une infection respiratoire haute virale (rhinopharyngite aiguë) et guérit spontanément. Les autres causes (bronchite aiguë, pneumonie, exacerbation d'asthme ou de BPCO, rhino-sinusite aiguë, RGO…) s'accompagnent d'autres symptômes.","src":"p. 114, 116"},{"id":"p204-qroc-005","type":"QROC","rank":"A","objective":"p204-obj-03","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Quelle exploration complémentaire systématique prévoit-on devant une toux aiguë isolée de l'adulte, à l'examen normal ?","answer":"Aucune","accept":["aucune","aucun examen","aucune exploration","pas d'exploration"],"keywords":["aucun"],"explanation":"Dans la très grande majorité des cas, la toux aiguë ne nécessite aucune exploration complémentaire. L'interrogatoire et un examen clinique minutieux (avec auscultation cardio-pulmonaire) suffisent.","src":"p. 114, 117"},{"id":"p204-qroc-006","type":"QROC","rank":"A","objective":"p204-obj-03","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Devant une toux aiguë, dans quelle situation réalise-t-on une radiographie de thorax ?","answer":"Examen physique anormal (bruits anormaux, crépitants)","accept":["examen physique anormal","examen clinique anormal","bruits anormaux à l'auscultation","crépitants","auscultation anormale"],"keywords":["anormal"],"explanation":"La radiographie de thorax est réservée aux toux aiguës avec examen physique anormal, notamment bruits anormaux à l'auscultation (crépitants…). D'autres examens se discutent seulement si l'on suspecte une pathologie autre qu'une infection haute ou une bronchite virale.","src":"p. 117"},{"id":"p204-qroc-007","type":"QROC","rank":"A","objective":"p204-obj-09","tags":["traitement","pièges"],"difficulty":1,"question":"Quel bénéfice apporte une antibiothérapie dans le traitement d'une toux aiguë, en dehors d'une infection bactérienne avérée ?","answer":"Aucun","accept":["aucun","aucun bénéfice","pas de bénéfice"],"keywords":["aucun"],"explanation":"Sans infection bactérienne avérée, une antibiothérapie n'apporte aucun bénéfice dans la toux aiguë. Il n'y a pas non plus lieu de prescrire un antitussif.","src":"p. 117"},{"id":"p204-qroc-008","type":"QROC","rank":"A","objective":"p204-obj-09","tags":["traitement","pièges"],"difficulty":2,"question":"Pour quelle raison les antitussifs contenant de la pholcodine ont-ils été retirés du marché ?","answer":"Risque d'allergie grave aux curares","accept":["allergie aux curares","allergie grave aux curares","curares","risque d'allergie aux curares"],"keywords":["curare"],"explanation":"La pholcodine a été retirée du marché car elle peut provoquer une allergie grave aux curares. Plus largement, les antitussifs et expectorants ont un rapport bénéfice/risque faible, avec des effets secondaires parfois importants.","src":"p. 117"},{"id":"p204-qroc-009","type":"QROC","rank":"A","objective":"p204-obj-03","tags":["suivi"],"difficulty":1,"question":"À quel délai organise-t-on un suivi après une toux aiguë, pour s'assurer de sa disparition ?","answer":"4 à 6 semaines","accept":["4 à 6 semaines","4-6 semaines","4 à 6 sem","entre 4 et 6 semaines"],"keywords":["4","6"],"explanation":"Un suivi à 4-6 semaines vérifie la disparition de la toux aiguë. Chez un fumeur, la consultation est aussi l'occasion de rappeler la nocivité du tabac et de conseiller l'arrêt définitif.","src":"p. 117"},{"id":"p204-qroc-010","type":"QROC","rank":"A","objective":"p204-obj-03","tags":["clinique"],"difficulty":2,"question":"Quelles trois zones doit-on inspecter impérativement devant une toux aiguë, en plus de l'auscultation cardio-pulmonaire ?","answer":"Fosses nasales, conduits auditifs, cavité buccale","accept":["fosses nasales, conduits auditifs et cavité buccale","fosses nasales, cavité buccale et conduits auditifs"],"keywords":["nasales","auditifs","buccale"],"explanation":"L'examen clinique est minutieux : inspection impérative des fosses nasales, des conduits auditifs et de la cavité buccale, et auscultation cardio-pulmonaire obligatoire.","src":"p. 117"},{"id":"p204-qroc-011","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quels sont les deux examens systématiques dans le bilan d'une toux chronique ?","answer":"Radiographie de thorax et spirométrie","accept":["radiographie thoracique et spirométrie","radio du thorax et spirométrie","RP et spirométrie","RP et EFR"],"keywords":["radio","spirom"],"explanation":"Radiographie de thorax et spirométrie sont systématiques en cas de toux chronique. Avant tout autre examen, on caractérise la toux et le profil du patient pour orienter la conduite à tenir.","src":"p. 114, 118"},{"id":"p204-qroc-012","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["étiologie"],"difficulty":2,"question":"En l'absence d'élément d'orientation, quelles trois causes fréquentes recherche-t-on en première intention devant une toux chronique ?","answer":"STOVAS (rhinosinusite), asthme, RGO","accept":["STOVAS, asthme et RGO","rhinosinusite chronique, asthme et reflux gastro-œsophagien","asthme, RGO et STOVAS"],"keywords":["stovas","asthme","rgo"],"explanation":"On recherche d'abord un STOVAS (rhinosinusite chronique), un asthme et un RGO ; si des arguments vont dans ce sens, on met en place un traitement d'épreuve. Les médicaments tussigènes sont aussi à éliminer.","src":"p. 114, 121"},{"id":"p204-qroc-013","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["étiologie","pièges"],"difficulty":2,"question":"Citez les trois traitements tussigènes à arrêter devant une toux chronique.","answer":"IEC, sartans, gliptines","accept":["IEC, sartans et gliptines","inhibiteurs de l'enzyme de conversion, sartans et gliptines","gliptines, sartans et IEC"],"keywords":["iec","sartan","gliptine"],"explanation":"Les IEC, les sartans et les gliptines sont tussigènes : on les arrête (en même temps que le tabac) pendant 4 semaines devant une toux chronique.","src":"p. 119"},{"id":"p204-qroc-014","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["clinique"],"difficulty":2,"question":"Vers quelles deux pathologies oriente une toux chronique productive ?","answer":"BPCO et dilatation des bronches","accept":["BPCO et DDB","BPCO, dilatation des bronches","dilatation des bronches et BPCO"],"keywords":["bpco","dilatation"],"explanation":"Une toux productive oriente vers une BPCO ou une dilatation des bronches ; une toux sèche vers un asthme ou une fibrose.","src":"p. 117"},{"id":"p204-qroc-015","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["clinique"],"difficulty":2,"question":"Vers quelles deux pathologies oriente une toux chronique sèche ?","answer":"Asthme et fibrose","accept":["asthme et fibrose pulmonaire","asthme, fibrose","fibrose et asthme"],"keywords":["asthme","fibrose"],"explanation":"Toux sèche → asthme ou fibrose ; toux productive → BPCO ou dilatation des bronches.","src":"p. 117"},{"id":"p204-qroc-016","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["clinique"],"difficulty":2,"question":"Une toux chronique nocturne oriente vers quelles deux causes fréquentes ?","answer":"Asthme et RGO","accept":["asthme et reflux gastro-œsophagien","asthme et reflux","RGO et asthme","reflux et asthme"],"keywords":["asthme","rgo"],"explanation":"Toux nocturne → asthme ou RGO ; toux uniquement diurne → toux par excès de sensibilité.","src":"p. 117"},{"id":"p204-qroc-017","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["clinique"],"difficulty":2,"question":"Vers quel type de toux chronique oriente une toux uniquement diurne ?","answer":"Toux par excès de sensibilité","accept":["excès de sensibilité","syndrome de toux par excès de sensibilité","toux par excès de sensibilité"],"keywords":["sensibilit"],"explanation":"Le syndrome de toux par excès de sensibilité est une toux primitive : déclenchée par des stimuli peu tussigènes ou non tussigènes (parole, rire, odeurs, air froid, décubitus…), uniquement diurne.","src":"p. 117, 119, 122"},{"id":"p204-qroc-018","type":"QROC","rank":"A","objective":"p204-obj-05","tags":["clinique"],"difficulty":1,"question":"Quel signe associé à une toux chronique oriente vers un reflux gastro-œsophagien ?","answer":"Le pyrosis","accept":["pyrosis","régurgitation acide","pyrosis et/ou régurgitation acide"],"keywords":["pyrosis"],"explanation":"Le pyrosis oriente vers un RGO ; un jetage ou une rhinorrhée postérieurs orientent vers une rhinosinusite chronique (STOVAS). Dans la toux chronique, les IPP ne se justifient que s'il existe des signes de RGO (pyrosis et/ou régurgitation acide).","src":"p. 118, 122"},{"id":"p204-qroc-019","type":"QROC","rank":"A","objective":"p204-obj-05","tags":["définition","clinique"],"difficulty":1,"question":"Que signifie l'acronyme STOVAS ?","answer":"Syndrome de toux d'origine des voies aériennes supérieures","accept":["syndrome de toux d'origine des voies aériennes supérieures","syndrome de toux des voies aériennes supérieures","syndrome de toux d'origine des VAS"],"keywords":["voies aériennes supérieures"],"explanation":"STOVAS = syndrome de toux d'origine des voies aériennes supérieures : écoulement ou rhinorrhée postérieurs chroniques dus à une rhinosinusite chronique.","src":"p. 114, 118"},{"id":"p204-qroc-020","type":"QROC","rank":"A","objective":"p204-obj-05","tags":["clinique"],"difficulty":2,"question":"Vers quel diagnostic orientent des crépitants secs à l'auscultation chez un patient qui tousse de façon chronique ?","answer":"Une pneumonie interstitielle diffuse","accept":["pneumopathie interstitielle diffuse","pneumonie interstitielle","pneumopathie interstitielle","PID"],"keywords":["interstiti"],"explanation":"Des crépitants secs orientent vers une pneumonie interstitielle diffuse ; des ronchi ou des sibilants orientent vers une pathologie bronchique.","src":"p. 118"},{"id":"p204-qroc-021","type":"QROC","rank":"A","objective":"p204-obj-05","tags":["complications"],"difficulty":1,"question":"Quelle complication de la toux chronique touche environ deux tiers des femmes ?","answer":"L'incontinence urinaire","accept":["incontinence urinaire","incontinence","fuites urinaires"],"keywords":["incontinence"],"explanation":"L'incontinence urinaire (+++, 2/3 des femmes) est une complication physique fréquente de la toux chronique, avec les troubles du sommeil, la fatigue, les fractures de côtes, la hernie inguinale, les vomissements ou l'hémorragie sous-conjonctivale.","src":"p. 118"},{"id":"p204-qroc-022","type":"QROC","rank":"A","objective":"p204-obj-05","tags":["complications"],"difficulty":1,"question":"Quel type de complication domine la toux chronique, les patients n'osant plus se rendre dans les lieux publics ou chez des proches ?","answer":"Le handicap social","accept":["handicap social","retentissement social","complications sociales"],"keywords":["social"],"explanation":"Les complications sont dominées par le handicap social ; le retentissement psychologique (dépression, anxiété) est également fréquent. La toux ne doit jamais être négligée, même en l'absence de pathologie grave.","src":"p. 118"},{"id":"p204-qroc-023","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["prévention","traitement"],"difficulty":1,"question":"Chez un fumeur qui consulte pour une toux, que doit-on proposer dans tous les cas ?","answer":"L'arrêt du tabac avec aide au sevrage","accept":["arrêt du tabac","sevrage tabagique","arrêt du tabagisme","aide au sevrage"],"keywords":["tabac"],"explanation":"Le tabagisme doit être arrêté et une aide au sevrage définitif apportée dans tous les cas, y compris lors d'une toux aiguë.","src":"p. 114, 117"},{"id":"p204-qroc-024","type":"QROC","rank":"A","objective":"p204-obj-08","tags":["urgence","diagnostic"],"difficulty":1,"question":"Que doit faire évoquer l'apparition ou la modification d'une toux chez un fumeur ?","answer":"Un cancer bronchique","accept":["cancer bronchique","cancer du poumon","cancer pulmonaire","cancer broncho-pulmonaire"],"keywords":["cancer"],"explanation":"L'apparition ou la modification de la toux chez un fumeur est un signe de gravité : on évoque un cancer bronchique. Toute suspicion impose un scanner thoracique, en plus des EFR et de la radiographie de thorax.","src":"p. 114, 119"},{"id":"p204-qroc-025","type":"QROC","rank":"A","objective":"p204-obj-08","tags":["imagerie","urgence"],"difficulty":1,"question":"Quel examen d'imagerie doit être pratiqué devant toute suspicion de cancer bronchique chez un patient qui tousse ?","answer":"Un scanner thoracique","accept":["scanner thoracique","TDM thoracique","tomodensitométrie thoracique","scanner","TDM"],"keywords":["thorac"],"explanation":"En cas de suspicion de cancer bronchique, un scanner thoracique doit être réalisé. En présence de signes de gravité, des examens complémentaires s'imposent d'emblée en plus des EFR et de la radiographie de thorax.","src":"p. 119"},{"id":"p204-qroc-026","type":"QROC","rank":"A","objective":"p204-obj-08","tags":["urgence","clinique"],"difficulty":1,"question":"Quel signe hémorragique figure parmi les signes de gravité d'une toux ?","answer":"L'hémoptysie","accept":["hémoptysie","une hémoptysie","crachat de sang"],"keywords":["hémoptysie"],"explanation":"Signes de gravité de la toux : altération de l'état général, dyspnée d'effort, hémoptysie, syndrome infectieux, apparition ou modification de la toux chez un fumeur, dysphonie/dysphagie/fausses routes, adénopathie cervicale suspecte, anomalie de l'examen cardiopulmonaire.","src":"p. 119"},{"id":"p204-qroc-027","type":"QROC","rank":"A","objective":"p204-obj-08","tags":["urgence","clinique"],"difficulty":2,"question":"Quels troubles de la voix et de la déglutition (trois termes) sont des signes de gravité d'une toux ?","answer":"Dysphonie, dysphagie, fausses routes","accept":["dysphonie, dysphagie et fausses routes","dysphagie, dysphonie, fausses routes"],"keywords":["dysphonie","dysphagie","fausses routes"],"explanation":"La dysphonie, la dysphagie et les fausses routes figurent avec l'hémoptysie, la dyspnée d'effort, l'altération de l'état général, le syndrome infectieux, les adénopathies cervicales suspectes et la modification de la toux d'un fumeur parmi les signes de gravité.","src":"p. 119"},{"id":"p204-qroc-028","type":"QROC","rank":"A","objective":"p204-obj-09","tags":["traitement"],"difficulty":1,"question":"Quel principe guide le traitement d'une toux chronique, plutôt que le traitement symptomatique ?","answer":"Un traitement avant tout étiologique","accept":["traitement étiologique","étiologique","rechercher et traiter la cause","traiter la cause"],"keywords":["etiolog"],"explanation":"Le traitement symptomatique de la toux chronique a peu de place : on privilégie la recherche du ou des facteurs étiologiques. Les antitussifs ne doivent pas être utilisés (non recommandés par la société européenne de pneumologie ni par la SPLF).","src":"p. 114, 121"},{"id":"p204-qroc-029","type":"QROC","rank":"A","objective":"p204-obj-04","tags":["définition"],"difficulty":1,"question":"Comment nomme-t-on une toux chronique sans cause retrouvée, ou qui persiste malgré le traitement des causes potentielles ?","answer":"Toux chronique réfractaire ou inexpliquée (TOCRI)","accept":["TOCRI","toux chronique réfractaire","toux chronique inexpliquée","toux réfractaire"],"keywords":["réfractaire"],"explanation":"Si aucune cause n'est retrouvée ou si aucun traitement n'a amélioré les causes potentielles, on parle de toux chronique réfractaire ou inexpliquée (TOCRI).","src":"p. 120"},{"id":"p204-qroc-030","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["traitement","prévention"],"difficulty":2,"question":"Pendant combien de temps arrête-t-on les traitements tussigènes (et le tabac) dans la démarche devant une toux chronique ?","answer":"4 semaines","accept":["4 semaines","au moins 4 semaines","pendant 4 semaines","quatre semaines"],"keywords":["4"],"explanation":"On arrête les traitements tussigènes (IEC, sartans, gliptines) et le tabac pendant 4 semaines (au moins pour le tabac), avant de conclure à la persistance de la toux.","src":"p. 119, 121"},{"id":"p204-qroc-031","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["pièges","prévention"],"difficulty":3,"question":"Quel phénomène transitoire peut survenir à l'arrêt du tabac chez le fumeur qui tousse, et qu'il faut lui annoncer ?","answer":"Une majoration paradoxale transitoire de la toux","accept":["majoration paradoxale de la toux","aggravation transitoire de la toux","majoration transitoire de la toux","aggravation de la toux","augmentation de la toux"],"keywords":["transitoire"],"explanation":"On prévient le fumeur qu'il existe une période réfractaire, variable selon les individus, avec une possible majoration paradoxale transitoire de la toux à l'arrêt du tabac.","src":"p. 119"},{"id":"p204-qroc-032","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["traitement"],"difficulty":2,"question":"Quelle durée minimale d'inhibiteurs de la pompe à protons prescrit-on pour une toux chronique attribuée à un RGO ?","answer":"Au moins 8 semaines","accept":["8 semaines","au moins 8 semaines","8 sem","huit semaines"],"keywords":["8"],"explanation":"RGO : IPP pour au moins 8 semaines, associés aux règles hygiéno-diététiques (+++).","src":"p. 122"},{"id":"p204-qroc-033","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["traitement","pièges"],"difficulty":2,"question":"Dans la toux chronique, à quelle condition les IPP se justifient-ils ?","answer":"Existence de signes de RGO (pyrosis, régurgitation acide)","accept":["signes de RGO","pyrosis","régurgitation acide","pyrosis et/ou régurgitation acide"],"keywords":["signes"],"explanation":"Dans la toux chronique, les IPP ne se justifient que s'il existe des signes de RGO (pyrosis et/ou régurgitation acide) : ils ne se prescrivent pas de façon systématique.","src":"p. 122"},{"id":"p204-qroc-034","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["traitement"],"difficulty":2,"question":"Quels traitements locaux associe-t-on pour une toux chronique due à une rhinosinusite chronique (STOVAS) ?","answer":"Lavage du nez et corticothérapie nasale","accept":["lavage nasal et corticoïdes nasaux","lavage du nez et corticoïdes nasaux","corticothérapie nasale et lavage du nez"],"keywords":["lavage","cortico"],"explanation":"STOVAS : lavage du nez, corticothérapie nasale, éviction des facteurs favorisants et éducation thérapeutique. Pour l'asthme : CSI ± BDLA ; pour le RGO : IPP.","src":"p. 122"},{"id":"p204-qroc-035","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["définition"],"difficulty":2,"question":"Comment appelle-t-on le déclenchement de la toux par des stimuli non tussigènes, comme la parole ou le rire ?","answer":"L'allotussie","accept":["allotussie","allo-tussie"],"keywords":["allotussie"],"explanation":"Allotussie = toux déclenchée par des stimuli non tussigènes (parole, rire). Dans le syndrome de toux par excès de sensibilité, il existe aussi une hypertussie (stimuli inhalés peu tussigènes) ; la physiopathologie serait proche de celle de la douleur neuropathique.","src":"p. 122"},{"id":"p204-qroc-036","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["définition"],"difficulty":2,"question":"Comment appelle-t-on la sensibilité augmentée de la toux à des stimuli inhalés peu tussigènes ?","answer":"L'hypertussie","accept":["hypertussie","hyper-tussie"],"keywords":["hypertussie"],"explanation":"Hypertussie = toux déclenchée par des stimuli peu tussigènes (sensibilité augmentée aux stimuli inhalés) ; allotussie = toux déclenchée par des stimuli non tussigènes. Les deux caractérisent le syndrome de toux par excès de sensibilité.","src":"p. 122"},{"id":"p204-qroc-037","type":"QROC","rank":"B","objective":"p204-obj-10","tags":["traitement"],"difficulty":2,"question":"Quelle classe de médicaments (deux molécules possibles) est proposée dans le syndrome de toux par excès de sensibilité ?","answer":"Anti-épileptiques (prégabaline ou gabapentine)","accept":["prégabaline ou gabapentine","prégabaline","gabapentine","anti-épileptiques"],"keywords":["epileptique"],"explanation":"Les traitements reposent sur les anti-épileptiques (prégabaline ou gabapentine) et la morphine à faible dose.","src":"p. 122"},{"id":"p204-qroc-038","type":"QROC","rank":"B","objective":"p204-obj-07","tags":["imagerie","pièges"],"difficulty":2,"question":"Dans quelle situation n'y a-t-il pas d'indication de scanner thoracique devant une toux chronique ?","answer":"Examen clinique et RP normaux, sans facteur de risque de cancer bronchique","accept":["examen clinique normal, radiographie normale et pas de facteur de risque de cancer bronchique","examen normal, radiographie normale, absence de facteurs de risque de cancer"],"keywords":["norma","cancer"],"explanation":"Pas de scanner thoracique si l'examen clinique et la radiographie de thorax sont normaux et en l'absence de facteur de risque de cancer bronchique. Toute suspicion de cancer bronchique impose en revanche un scanner.","src":"p. 118-119"},{"id":"p204-qcm-101","type":"QRM","rank":"A","objective":"p204-obj-02","tags":["définition"],"difficulty":1,"stem":"Parmi les propositions suivantes concernant la toux de l'adulte, lesquelles sont exactes ?","options":[{"t":"Une toux de 4 semaines est dite chronique","ok":false,"why":"Chronique = plus de 8 semaines ; entre 3 et 8 semaines, la toux est subaiguë."},{"t":"Une toux aiguë évolue depuis moins de 3 semaines","ok":true,"why":"C'est la définition de la toux aiguë."},{"t":"Une toux chronique s'améliore en général spontanément","ok":false,"why":"Elle ne s'améliore pas spontanément et nécessite une prise en charge spécifique."},{"t":"Une toux chronique évolue depuis plus de 8 semaines","ok":true,"why":"C'est la définition de la toux chronique."},{"t":"Une toux aiguë isolée est le plus souvent d'origine virale","ok":true,"why":"Elle accompagne le plus souvent une infection respiratoire haute virale et s'améliore spontanément en 3 semaines."}],"explanation":"Toux aiguë < 3 semaines, subaiguë entre 3 et 8 semaines, chronique > 8 semaines.","src":"p. 114-116"},{"id":"p204-qcm-102","type":"QRM","rank":"A","objective":"p204-obj-03","tags":["diagnostic","traitement"],"difficulty":2,"stem":"Un homme de 35 ans consulte pour une toux apparue depuis 4 jours avec une rhinorrhée. L'examen clinique, auscultation comprise, est normal. Quelles propositions sont exactes ?","options":[{"t":"Aucune exploration complémentaire n'est nécessaire","ok":true,"why":"Dans la très grande majorité des cas, la toux aiguë n'en nécessite pas."},{"t":"Une antibiothérapie systématique est indiquée","ok":false,"why":"Elle n'apporte aucun bénéfice en dehors d'une infection bactérienne avérée."},{"t":"Il s'agit le plus probablement d'une infection respiratoire haute virale","ok":true,"why":"C'est la cause très majoritaire des toux aiguës isolées ; elle s'améliore spontanément."},{"t":"Un traitement antitussif doit être prescrit","ok":false,"why":"Il n'y a pas lieu d'en prescrire."},{"t":"Un suivi à 4-6 semaines est organisé pour vérifier la disparition de la toux","ok":true,"why":"Le suivi s'assure de la disparition de la toux."}],"explanation":"Toux aiguë isolée : infection respiratoire haute virale, pas d'exploration, pas d'antibiotique ni d'antitussif, suivi à 4-6 semaines.","src":"p. 114, 116-117"},{"id":"p204-qcm-103","type":"QRM","rank":"A","objective":"p204-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Quels examens sont systématiques dans le bilan d'une toux chronique de l'adulte ?","options":[{"t":"Radiographie de thorax","ok":true,"why":"Elle est systématique, avec la spirométrie."},{"t":"Scanner thoracique","ok":false,"why":"Pas d'indication si l'examen clinique et la radiographie sont normaux, sans facteur de risque de cancer bronchique."},{"t":"pH-métrie des 24 heures","ok":false,"why":"Réservée à des situations particulières (toux post-prandiale, signes de RGO sans efficacité des IPP)."},{"t":"Spirométrie","ok":true,"why":"Elle est systématique, avec la radiographie de thorax."},{"t":"Fibroscopie bronchique","ok":false,"why":"Discutée selon le contexte si la toux persiste : aucun examen n'est systématique au-delà de la radiographie et de la spirométrie."}],"explanation":"Radiographie de thorax et spirométrie sont systématiques ; les autres explorations dépendent du contexte et des caractéristiques de la toux.","src":"p. 114, 118, 120"},{"id":"p204-qcm-104","type":"QRM","rank":"A","objective":"p204-obj-04","tags":["étiologie"],"difficulty":2,"stem":"Un patient de 45 ans, non fumeur, tousse depuis 12 semaines. L'examen clinique et la radiographie de thorax sont normaux. Quelles causes fréquentes faut-il rechercher en première intention ?","options":[{"t":"Une sarcoïdose","ok":false,"why":"Cause moins fréquente, à rechercher en 2e intention."},{"t":"Un STOVAS (rhinosinusite chronique)","ok":true,"why":"Cause fréquente, avec l'asthme, le RGO et les médicaments."},{"t":"Un syndrome d'apnées obstructives du sommeil","ok":false,"why":"Cause moins fréquente, à rechercher en 2e intention."},{"t":"Un asthme","ok":true,"why":"Cause fréquente de toux chronique à radiographie normale chez le non-fumeur."},{"t":"Un traitement tussigène (IEC, sartans, gliptines)","ok":true,"why":"À rechercher et à arrêter pendant 4 semaines."}],"explanation":"Causes fréquentes : STOVAS, asthme, RGO, médicaments, BPCO. Causes moins fréquentes, en 2e intention : pneumonies interstitielles diffuses, cancer bronchique, épanchement pleural, dilatation des bronches, SAOS, causes cardiaques ou neurologiques, toux psychogène.","src":"p. 114, 119"},{"id":"p204-qcm-105","type":"QRM","rank":"A","objective":"p204-obj-05","tags":["clinique"],"difficulty":2,"stem":"Quelles orientations diagnostiques sont exactes devant une toux chronique ?","options":[{"t":"Une toux sèche oriente vers une BPCO","ok":false,"why":"Toux sèche → asthme ou fibrose ; la BPCO donne plutôt une toux productive."},{"t":"Une toux productive oriente vers une BPCO ou une dilatation des bronches","ok":true,"why":"C'est l'orientation de la toux productive."},{"t":"Une toux uniquement diurne oriente vers un RGO","ok":false,"why":"Elle oriente vers une toux par excès de sensibilité ; la toux nocturne oriente vers un asthme ou un RGO."},{"t":"Une toux nocturne oriente vers un asthme ou un RGO","ok":true,"why":"C'est l'orientation de la toux nocturne."},{"t":"Des crépitants secs orientent vers une pneumonie interstitielle diffuse","ok":true,"why":"Des ronchi ou des sibilants orientent plutôt vers une pathologie bronchique."}],"explanation":"Sèche → asthme, fibrose ; productive → BPCO, dilatation des bronches ; nocturne → asthme, RGO ; uniquement diurne → excès de sensibilité ; pyrosis → RGO ; jetage postérieur → STOVAS.","src":"p. 117-118"},{"id":"p204-qcm-106","type":"QRM","rank":"A","objective":"p204-obj-08","tags":["urgence","clinique"],"difficulty":1,"stem":"Quels éléments constituent des signes de gravité devant une toux ?","options":[{"t":"Une hémoptysie","ok":true,"why":"C'est un signe de gravité."},{"t":"Un pyrosis","ok":false,"why":"Il oriente vers un RGO ; ce n'est pas un signe de gravité."},{"t":"Une altération de l'état général","ok":true,"why":"Elle figure parmi les signes de gravité."},{"t":"Une toux survenant uniquement la nuit","ok":false,"why":"Elle oriente vers un asthme ou un RGO."},{"t":"Une dysphonie, une dysphagie ou des fausses routes","ok":true,"why":"Ils figurent parmi les signes de gravité."}],"explanation":"Autres signes de gravité : dyspnée d'effort, syndrome infectieux, apparition ou modification de la toux chez un fumeur, adénopathie cervicale suspecte, anomalie de l'examen cardiopulmonaire. Des examens complémentaires s'imposent alors d'emblée.","src":"p. 119"},{"id":"p204-qcm-107","type":"QRM","rank":"A","objective":"p204-obj-04","tags":["prévention","pièges"],"difficulty":3,"stem":"Chez un patient qui tousse de façon chronique, quelles propositions concernant le tabac et les médicaments sont exactes ?","options":[{"t":"Les IEC, sartans et gliptines sont tussigènes et à arrêter 4 semaines","ok":true,"why":"Ces traitements sont arrêtés, comme le tabac, pendant 4 semaines."},{"t":"Une toux isolée chez un fumeur actif ne nécessite pas de prise en charge","ok":false,"why":"La toux chronique, même isolée et même chez un fumeur actif, nécessite une prise en charge progressive."},{"t":"L'arrêt du tabac est proposé dans tous les cas, avec une aide au sevrage","ok":true,"why":"Une aide au sevrage définitif doit être apportée dans tous les cas."},{"t":"On attend l'échec des traitements avant de proposer l'arrêt du tabac","ok":false,"why":"L'arrêt du tabac est proposé dans tous les cas, sans attendre."},{"t":"À l'arrêt du tabac, la toux peut transitoirement s'aggraver","ok":true,"why":"Il existe une période réfractaire, avec majoration paradoxale transitoire possible de la toux."}],"explanation":"Devant une toux chronique : arrêt du tabac (aide au sevrage dans tous les cas) et des traitements tussigènes pendant 4 semaines, en prévenant le fumeur d'une possible aggravation transitoire.","src":"p. 114, 119"},{"id":"p204-qcm-108","type":"QRM","rank":"B","objective":"p204-obj-10","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant la toux chronique attribuée à un reflux gastro-œsophagien, quelles propositions sont exactes ?","options":[{"t":"Les IPP sont prescrits de façon systématique devant toute toux chronique","ok":false,"why":"Ils ne se justifient que s'il existe des signes de RGO (pyrosis et/ou régurgitation acide)."},{"t":"Les IPP sont prescrits pour au moins 8 semaines","ok":true,"why":"La durée minimale est de 8 semaines."},{"t":"Une cure de 2 semaines d'IPP suffit","ok":false,"why":"La durée est d'au moins 8 semaines."},{"t":"Les règles hygiéno-diététiques font partie du traitement","ok":true,"why":"Elles sont associées aux IPP (+++)."},{"t":"Les IPP ne se justifient que s'il existe un pyrosis ou une régurgitation acide","ok":true,"why":"Dans la toux chronique, ils ne se justifient que s'il existe des signes de RGO."}],"explanation":"Toux et RGO : IPP pour au moins 8 semaines, règles hygiéno-diététiques, et seulement en présence de signes de RGO.","src":"p. 122"},{"id":"p204-qcm-109","type":"QRM","rank":"B","objective":"p204-obj-10","tags":["clinique"],"difficulty":2,"stem":"Quelles caractéristiques évoquent un syndrome de toux par excès de sensibilité ?","options":[{"t":"Une toux déclenchée par la parole ou le rire","ok":true,"why":"C'est l'allotussie : déclenchement par des stimuli non tussigènes."},{"t":"Une toux productive avec expectoration abondante","ok":false,"why":"Une toux productive oriente vers une BPCO ou une dilatation des bronches."},{"t":"Une toux paroxystique difficile à contrôler","ok":true,"why":"C'est l'un des critères du tableau des caractéristiques."},{"t":"Une toux survenant uniquement la nuit","ok":false,"why":"Une toux nocturne oriente vers un asthme ou un RGO ; l'excès de sensibilité donne une toux diurne."},{"t":"Une irritation du larynx ou du pharynx, avec paresthésies des voies aériennes supérieures","ok":true,"why":"C'est le premier critère clinique, diagnostiqué à l'interrogatoire."}],"explanation":"Le diagnostic se fait à l'interrogatoire : irritation laryngo-pharyngée, allotussie, hypertussie, toux paroxystique difficile à contrôler, déclencheurs (chant, parole, rire, air froid, parfums, décubitus, repas, exercice).","src":"p. 117, 122"},{"id":"p204-qcm-110","type":"QRM","rank":"B","objective":"p204-obj-07","tags":["imagerie"],"difficulty":2,"stem":"Quelles propositions concernant l'imagerie thoracique devant une toux de l'adulte sont exactes ?","options":[{"t":"Une radiographie de thorax est systématique devant toute toux aiguë","ok":false,"why":"Dans la très grande majorité des cas, la toux aiguë ne nécessite aucune exploration."},{"t":"Un scanner thoracique est réalisé en cas de suspicion de cancer bronchique","ok":true,"why":"Toute suspicion de cancer bronchique conduit à un scanner thoracique."},{"t":"Un scanner thoracique est systématique devant toute toux chronique","ok":false,"why":"Pas d'indication si l'examen clinique et la radiographie sont normaux, sans facteur de risque de cancer bronchique."},{"t":"Une radiographie de thorax est faite devant une toux aiguë à l'examen physique anormal","ok":true,"why":"Notamment en cas de bruits anormaux à l'auscultation (crépitants…)."},{"t":"Il n'y a pas d'indication de scanner si l'examen et la radiographie sont normaux, sans facteur de risque de cancer","ok":true,"why":"C'est la situation où le scanner thoracique n'a pas d'indication."}],"explanation":"Toux aiguë : radiographie seulement si examen anormal. Toux chronique : radiographie et spirométrie systématiques ; scanner si suspicion de cancer bronchique, pas si tout est normal et sans facteur de risque.","src":"p. 117-119"},{"id":"p204-qcm-111","type":"QRM","rank":"A","objective":"p204-obj-09","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant les antitussifs dans la toux aiguë de l'adulte, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Ils sont recommandés en première intention","ok":false,"why":"Il n'y a pas lieu d'en prescrire."},{"t":"Leur efficacité est solidement démontrée","ok":false,"why":"Les preuves scientifiques de leur efficacité restent à démontrer."},{"t":"Il n'y a pas lieu d'en prescrire","ok":true,"why":"Leur rapport bénéfice/risque est faible."},{"t":"Leurs effets secondaires sont toujours négligeables","ok":false,"why":"Ils sont parfois importants."},{"t":"Ceux à base de pholcodine ont été retirés car inefficaces","ok":false,"why":"Ils ont été retirés en raison du risque d'allergie grave aux curares."}],"explanation":"Dans la toux aiguë, ni antibiothérapie (hors infection bactérienne avérée) ni antitussif : le rapport bénéfice/risque des antitussifs et expectorants est faible.","src":"p. 117"},{"id":"p204-qcm-112","type":"QRM","rank":"A","objective":"p204-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement symptomatique de la toux chronique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il constitue le traitement de référence","ok":false,"why":"Il a peu de place en pratique."},{"t":"Les antitussifs sont recommandés par la société européenne de pneumologie","ok":false,"why":"Ils ne sont recommandés ni par la société européenne de pneumologie ni par la SPLF."},{"t":"Il a peu de place : on privilégie la recherche étiologique","ok":true,"why":"On cherche le ou les facteurs étiologiques."},{"t":"Il doit être débuté d'emblée, avant toute recherche étiologique","ok":false,"why":"Le traitement d'une toux chronique est avant tout étiologique."},{"t":"Les antitussifs sont utiles en cas de toux chronique réfractaire","ok":false,"why":"Les antitussifs ne doivent pas être utilisés ; dans le syndrome d'excès de sensibilité, on propose des anti-épileptiques ou de la morphine à faible dose."}],"explanation":"Le traitement d'une toux chronique est avant tout étiologique ; les antitussifs ne doivent pas être utilisés.","src":"p. 114, 121-122"},{"id":"p204-qcm-113","type":"QRM","rank":"A","objective":"p204-obj-05","tags":["complications"],"difficulty":2,"stem":"Concernant les complications de la toux chronique, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Les complications sont exclusivement physiques","ok":false,"why":"Elles sont aussi sociales (+++) et psychologiques (dépression, anxiété)."},{"t":"L'incontinence urinaire est une complication exceptionnelle","ok":false,"why":"Elle touche environ 2/3 des femmes."},{"t":"Le handicap social domine ; ne jamais négliger la toux","ok":true,"why":"La toux ne doit jamais être négligée par le médecin, même en l'absence de pathologie grave."},{"t":"Les fractures de côtes ne s'observent pas dans la toux chronique","ok":false,"why":"Elles figurent parmi les complications physiques."},{"t":"Le retentissement psychologique est rare","ok":false,"why":"Il est fréquent."}],"explanation":"Complications physiques (sommeil, fatigue, fractures de côtes, incontinence urinaire…), sociales (+++) et psychologiques (+++) : le handicap social est au premier plan.","src":"p. 118"},{"id":"p204-qcm-114","type":"QRM","rank":"B","objective":"p204-obj-06","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant le réflexe de toux, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Les nocicepteurs détectent les stimuli mécaniques","ok":false,"why":"Ils détectent les irritants chimiques ; les mécanorécepteurs détectent les stimuli mécaniques."},{"t":"Les afférences passent par le nerf vague","ok":true,"why":"Elles convergent via le nerf vague jusqu'au noyau solitaire du tronc cérébral, relié aux centres respiratoires."},{"t":"Les mécanorécepteurs sont associés à des fibres C non myélinisées","ok":false,"why":"Ils transmettent par des fibres myélinisées Aδ, rapides ; les fibres C non myélinisées sont celles des nocicepteurs."},{"t":"La toux échappe à tout contrôle cortical","ok":false,"why":"Il existe une commande volontaire pour inhiber ou activer la toux."},{"t":"La toux est un mécanisme spécifique de défense","ok":false,"why":"C'est un mécanisme non spécifique de défense des voies aériennes."}],"explanation":"Deux types de récepteurs (nocicepteurs, mécanorécepteurs), voies afférentes par le nerf vague vers le noyau solitaire du tronc cérébral, centres respiratoires, et contrôle par le cortex.","src":"p. 115"},{"id":"p204-qcm-115","type":"QRM","rank":"A","objective":"p204-obj-04","tags":["étiologie"],"difficulty":2,"stem":"Quelle(s) cause(s) de toux chronique fait (font) partie des causes moins fréquentes, à rechercher en deuxième intention ?","options":[{"t":"Un reflux gastro-œsophagien acide ou non acide","ok":false,"why":"Cause fréquente, à rechercher en première intention."},{"t":"Une rhinosinusite chronique (atteinte rhino-sinusienne)","ok":false,"why":"Cause fréquente (STOVAS)."},{"t":"Un syndrome d'apnées du sommeil","ok":true,"why":"Cause moins fréquente, comme les pneumonies interstitielles diffuses, le cancer bronchique, l'épanchement pleural, la dilatation des bronches, les causes cardiaques ou neurologiques."},{"t":"Une BPCO (broncho-pneumopathie chronique obstructive)","ok":false,"why":"Classée parmi les causes fréquentes."},{"t":"Un traitement tussigène (IEC ou gliptine)","ok":false,"why":"Les médicaments sont une cause fréquente."}],"explanation":"Causes fréquentes (1re intention) : STOVAS, asthme, RGO, médicaments, BPCO. Causes moins fréquentes (2e intention) : pneumonies interstitielles diffuses, cancer bronchique, épanchement pleural, dilatation des bronches, SAOS, causes cardiaques et neurologiques, toux psychogène.","src":"p. 118-119"},{"id":"p204-qcm-116","type":"QRM","rank":"A","objective":"p204-obj-04","tags":["étiologie","traitement"],"difficulty":2,"stem":"Une patiente de 55 ans, traitée par un IEC pour une hypertension artérielle, tousse depuis 10 semaines. L'examen clinique et la radiographie de thorax sont normaux. Quelle(s) mesure(s) est (sont) recommandée(s) ?","options":[{"t":"Remplacer l'IEC par un sartan","ok":false,"why":"Les sartans sont aussi tussigènes : IEC, sartans et gliptines sont arrêtés pendant 4 semaines."},{"t":"Prescrire un antitussif","ok":false,"why":"Les antitussifs ne doivent pas être utilisés."},{"t":"Arrêter l'IEC pendant 4 semaines","ok":true,"why":"C'est un traitement tussigène à arrêter."},{"t":"Réaliser d'emblée un scanner thoracique","ok":false,"why":"Pas d'indication si l'examen clinique et la radiographie sont normaux, sans facteur de risque de cancer bronchique."},{"t":"Débuter d'emblée une fibroscopie bronchique","ok":false,"why":"Aucun examen n'est systématique au-delà de la radiographie et de la spirométrie ; l'endoscopie bronchique se discute si la toux persiste."}],"explanation":"Devant une toux chronique, on arrête les traitements tussigènes (IEC, sartans, gliptines) et le tabac pendant 4 semaines, avant de pousser les explorations.","src":"p. 119-121"},{"id":"p204-qru-101","type":"QRU","rank":"A","objective":"p204-obj-02","tags":["définition"],"difficulty":2,"stem":"Un homme de 40 ans tousse depuis 5 semaines. Comment qualifier sa toux ?","options":[{"t":"Toux aiguë","ok":false,"why":"Une toux aiguë dure moins de 3 semaines."},{"t":"Toux chronique","ok":false,"why":"Une toux chronique dure plus de 8 semaines."},{"t":"Toux subaiguë","ok":true,"why":"Entre 3 et 8 semaines, la toux est subaiguë."},{"t":"Toux chronique réfractaire (TOCRI)","ok":false,"why":"Ce terme s'applique à une toux chronique sans cause retrouvée ou persistante malgré la prise en charge."},{"t":"Toux psychogène","ok":false,"why":"C'est une étiologie, et non une classification selon la durée."}],"explanation":"Toux aiguë < 3 semaines ; subaiguë entre 3 et 8 semaines ; chronique > 8 semaines.","src":"p. 115"},{"id":"p204-qru-102","type":"QRU","rank":"A","objective":"p204-obj-03","tags":["étiologie"],"difficulty":1,"stem":"Une femme de 28 ans consulte pour une toux isolée apparue il y a 3 jours, sans autre symptôme, avec un examen clinique normal. Quelle est l'étiologie la plus probable ?","options":[{"t":"Une bronchite aiguë ou une pneumonie","ok":false,"why":"Les infections respiratoires basses sont moins fréquentes, la pneumonie plus rare encore."},{"t":"Une embolie pulmonaire","ok":false,"why":"Cause rare de toux aiguë."},{"t":"Une rhinopharyngite virale","ok":true,"why":"Les infections respiratoires hautes (+++) expliquent très majoritairement une toux aiguë isolée."},{"t":"Une insuffisance cardiaque gauche","ok":false,"why":"Cause rare de toux aiguë."},{"t":"Un cancer bronchique","ok":false,"why":"Étiologie de toux chronique, moins fréquente."}],"explanation":"Isolée, la toux aiguë est très majoritairement secondaire à une infection respiratoire haute d'origine virale, qui s'améliore spontanément.","src":"p. 116"},{"id":"p204-qru-103","type":"QRU","rank":"A","objective":"p204-obj-05","tags":["clinique"],"difficulty":1,"stem":"Un homme de 30 ans, non fumeur, tousse depuis 3 mois et signale un écoulement postérieur dans la gorge. Quelle étiologie fréquente faut-il évoquer en priorité ?","options":[{"t":"Un reflux gastro-œsophagien","ok":false,"why":"Il est évoqué devant un pyrosis."},{"t":"Une pneumonie interstitielle diffuse","ok":false,"why":"Elle est évoquée devant des crépitants secs à l'auscultation."},{"t":"Une dilatation des bronches","ok":false,"why":"Elle est évoquée devant une toux productive."},{"t":"Une rhinosinusite chronique","ok":true,"why":"Un jetage ou une rhinorrhée postérieurs orientent vers une rhinosinusite chronique, appelée aussi STOVAS."},{"t":"Un asthme","ok":false,"why":"L'asthme est évoqué devant une toux sèche ou nocturne ; ici, c'est l'écoulement postérieur qui oriente."}],"explanation":"Jetage ou rhinorrhée postérieurs → rhinosinusite chronique (STOVAS) ; pyrosis → RGO ; crépitants secs → pneumonie interstitielle diffuse ; ronchi ou sibilants → pathologie bronchique.","src":"p. 118"},{"id":"p204-qru-104","type":"QRU","rank":"A","objective":"p204-obj-08","tags":["urgence","imagerie"],"difficulty":2,"stem":"Un fumeur de 58 ans consulte parce que sa toux habituelle a changé depuis 3 semaines ; il a craché du sang. Quel examen est indiqué, en plus de la radiographie de thorax et des EFR ?","options":[{"t":"Un traitement d'épreuve par IPP pendant 8 semaines","ok":false,"why":"Le traitement d'épreuve s'adresse aux causes fréquentes, en l'absence de signe de gravité."},{"t":"Une pH-métrie des 24 heures","ok":false,"why":"Réservée aux toux post-prandiales ou aux signes de RGO sans efficacité des IPP."},{"t":"Un scanner thoracique","ok":true,"why":"Toux modifiée chez un fumeur et hémoptysie sont des signes de gravité : en cas de suspicion de cancer bronchique, on réalise un scanner thoracique."},{"t":"Un enregistrement du sommeil","ok":false,"why":"Discuté en cas de toux persistante sans orientation, pas dans cette situation."},{"t":"Aucun, avant 8 semaines d'évolution","ok":false,"why":"En présence de signes de gravité, les examens complémentaires s'imposent d'emblée."}],"explanation":"L'apparition ou la modification de la toux chez un fumeur fait évoquer un cancer bronchique ; les signes de gravité imposent des examens d'emblée, dont le scanner thoracique.","src":"p. 114, 119"},{"id":"p204-qru-105","type":"QRU","rank":"B","objective":"p204-obj-10","tags":["traitement"],"difficulty":2,"stem":"Quel traitement local est proposé pour une toux chronique liée à une rhinosinusite chronique (STOVAS) ?","options":[{"t":"Une antibiothérapie prolongée par voie orale","ok":false,"why":"Le traitement repose sur le lavage du nez et la corticothérapie nasale, non sur une antibiothérapie."},{"t":"Des inhibiteurs de la pompe à protons","ok":false,"why":"Traitement de la toux liée à un RGO."},{"t":"Lavage du nez et corticothérapie nasale","ok":true,"why":"Associés à l'éviction des facteurs favorisants et à l'éducation thérapeutique."},{"t":"Des corticoïdes inhalés, avec ou sans BDLA","ok":false,"why":"Traitement de la toux liée à un asthme."},{"t":"De la morphine à faible dose","ok":false,"why":"Proposée dans la toux par excès de sensibilité."}],"explanation":"STOVAS : lavage du nez, corticothérapie nasale, éviction des facteurs favorisants, éducation thérapeutique.","src":"p. 122"},{"id":"p204-qru-106","type":"QRU","rank":"B","objective":"p204-obj-10","tags":["traitement"],"difficulty":2,"stem":"Quels médicaments sont proposés dans le syndrome de toux par excès de sensibilité ?","options":[{"t":"Un IEC ou un sartan","ok":false,"why":"Ces traitements sont tussigènes : on les arrête devant une toux chronique."},{"t":"Des IPP pendant au moins 8 semaines","ok":false,"why":"Traitement de la toux liée à un RGO."},{"t":"Des corticoïdes inhalés associés à un BDLA","ok":false,"why":"Traitement de la toux liée à un asthme."},{"t":"Prégabaline ou gabapentine","ok":true,"why":"Ce sont des anti-épileptiques ; la morphine à faible dose est l'autre option."},{"t":"Un antitussif contenant de la pholcodine","ok":false,"why":"Retiré du marché (allergie grave aux curares) ; les antitussifs ne sont pas recommandés."}],"explanation":"Dans le syndrome de toux par excès de sensibilité (TOCRI), les traitements reposent sur les anti-épileptiques (prégabaline, gabapentine) et la morphine à faible dose.","src":"p. 117, 122"},{"id":"p204-qru-107","type":"QRU","rank":"A","objective":"p204-obj-03","tags":["étiologie"],"difficulty":2,"stem":"Parmi les causes suivantes de toux aiguë de l'adulte, laquelle est qualifiée de rare ?","options":[{"t":"Une rhinopharyngite aiguë","ok":false,"why":"Cause la plus fréquente (+++)."},{"t":"Une bronchite aiguë","ok":false,"why":"Infection respiratoire basse, cause principale de toux aiguë."},{"t":"Une exacerbation d'asthme","ok":false,"why":"Cause principale de toux aiguë."},{"t":"Une rhino-sinusite aiguë","ok":false,"why":"Cause principale de toux aiguë."},{"t":"Une embolie pulmonaire","ok":true,"why":"Cause rare, comme l'insuffisance cardiaque gauche, le pneumothorax et les pleurésies."}],"explanation":"Causes principales de toux aiguë : infections respiratoires hautes (+++), infections respiratoires basses, exacerbations d'asthme et de BPCO, rhino-sinusite aiguë, RGO. Causes rares : insuffisance cardiaque gauche, embolie pulmonaire, pneumothorax et pleurésies.","src":"p. 116"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p204-pareto","points":[{"id":"p204-par-01","rank":"A","cat":"définition","text":"Toux **aiguë < 3 sem**, **chronique > 8 sem**, subaiguë entre les deux ; la chronique ne guérit pas spontanément → prise en charge spécifique","src":"p. 114-115"},{"id":"p204-par-02","rank":"A","cat":"étiologie","text":"Toux aiguë isolée = **infection respiratoire haute virale** : pas d'exploration, **pas d'antibiotique**, **pas d'antitussif** ; suivi à 4-6 sem","src":"p. 116-117"},{"id":"p204-par-03","rank":"A","cat":"examen","text":"Toux chronique : **RP + spirométrie systématiques** ; scanner si **suspicion de cancer bronchique** ; pas de scanner si examen et RP normaux sans FDR de cancer","src":"p. 114, 118-119"},{"id":"p204-par-04","rank":"A","cat":"étiologie","text":"Causes fréquentes de toux chronique : **STOVAS, asthme, RGO**, médicaments (**IEC, sartans, gliptines**), BPCO ; PID, cancer, SAOS = 2e intention","src":"p. 119, 121"},{"id":"p204-par-05","rank":"A","cat":"clinique","text":"Toux sèche → **asthme, fibrose** ; productive → **BPCO, dilatation des bronches** ; nocturne → **asthme, RGO** ; uniquement diurne → excès de sensibilité","src":"p. 117"},{"id":"p204-par-06","rank":"A","cat":"clinique","text":"Pyrosis → RGO ; jetage/rhinorrhée postérieurs → **STOVAS** (rhinosinusite chronique) ; crépitants secs → **PID** ; ronchi, sibilants → pathologie bronchique","src":"p. 118"},{"id":"p204-par-07","rank":"A","cat":"gravité","text":"Signes de gravité : AEG, dyspnée d'effort, **hémoptysie**, syndrome infectieux, dysphonie/dysphagie, ADP cervicale, **toux modifiée chez un fumeur** → cancer → **scanner**","src":"p. 114, 119"},{"id":"p204-par-08","rank":"A","cat":"traitement","text":"Démarche : signes de gravité ? → EVA → arrêt **tabac + tussigènes 4 sem** → rechercher STOVAS/asthme/RGO → **traitement d'épreuve** si arguments","src":"p. 119-121"},{"id":"p204-par-09","rank":"A","cat":"piège","text":"**Aucun antitussif** (aiguë comme chronique) ; **pholcodine** retirée (allergie aux curares) ; le traitement d'une toux chronique est avant tout **étiologique**","src":"p. 114, 117, 121"},{"id":"p204-par-10","rank":"A","cat":"piège","text":"Arrêt du tabac **dans tous les cas**, avec aide au sevrage ; à l'arrêt, la toux peut **s'aggraver transitoirement** (période réfractaire)","src":"p. 114, 119"},{"id":"p204-par-11","rank":"A","cat":"traitement","text":"STOVAS : **lavage du nez + corticoïdes nasaux** ; asthme : CSI ± BDLA ; RGO : **IPP ≥ 8 sem**, seulement si pyrosis/régurgitation acide","src":"p. 122"},{"id":"p204-par-12","rank":"A","cat":"clinique","text":"Complications : **handicap social** (+++), psychologique, **incontinence urinaire** (2/3 des femmes), fractures de côtes ; la toux n'est jamais à négliger","src":"p. 118"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
